define(["jquery"],function($){"use strict";var SELECT_ALL='[data-action="local-backupftp-select-all"]';var DESELECT_ALL='[data-action="local-backupftp-deselect-all"]';var NODE='[data-region="local-backupftp-node"]';var TREE='[data-region="local-backupftp-tree"]';var getScope=function(element){var scope=$(element).closest(NODE);if(!scope.length){scope=$(element).closest(TREE)}return scope};var setChecked=function(scope,checked){scope.find('input[type="checkbox"]').prop("checked",checked).trigger("change")};var init=function(){$(document).off("click.localBackupftpSelector",SELECT_ALL).on("click.localBackupftpSelector",SELECT_ALL,function(e){e.preventDefault();setChecked(getScope(this),true)});$(document).off("click.localBackupftpSelector",DESELECT_ALL).on("click.localBackupftpSelector",DESELECT_ALL,function(e){e.preventDefault();setChecked(getScope(this),false)})};return{init:init}});